const NEWS_CATEGORIES = ['Politics & Policy', 'Business & Economy', 'Science & Technology', 'World & Conflict'] as const;
type NewsCategory = (typeof NEWS_CATEGORIES)[number];

// Best-effort extraction of a concrete "Month D, YYYY" date out of free-text date
// strings. Returns null when no parseable date is present, treated as "unknown"
// rather than sorted arbitrarily.
function parsePublishedDate(dateStr: string): Date | null {
  const match = dateStr.match(/([A-Z][a-z]+ \d{1,2},\s*\d{4})/);
  if (!match) return null;
  const parsed = new Date(match[1]);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function relativeTime(dateObj: Date | null, fallback: string): string {
  if (!dateObj) return fallback;
  const now = new Date();
  const diffDays = Math.floor((now.getTime() - dateObj.getTime()) / 86400000);
  if (diffDays <= 0) return 'Today';
  if (diffDays === 1) return '1 day ago';
  if (diffDays < 30) return `${diffDays} days ago`;
  if (diffDays < 365) return `${Math.floor(diffDays / 30)} mo ago`;
  return dateObj.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
}

